            if known:
                fill = Counter(known).most_common(1)[0][0]
                for c, v in enumerate(row):
                    if v == 0:
                        out[r][c] = fill
            continue

        # Infer the row's repeating color sequence from the undamaged right
        # portion. The stream may use different sequence lengths in instances.
        samples = [(c, row[c]) for c in range(8, w) if row[c] != 0]
        if not samples:
            samples = [(c, row[c]) for c in range(3, w) if row[c] != 0]
        best_period = None
        best_errors = None
        for p in range(2, 11):
            by_residue = {}
            for c, value in samples:
                by_residue.setdefault(c % p, []).append(value)
            errors = sum(len(vs) - Counter(vs).most_common(1)[0][1]
                         for vs in by_residue.values())
            if best_errors is None or errors < best_errors:
                best_period, best_errors = p, errors
        p = best_period
        by_residue = {}
        for c, value in samples:
            by_residue.setdefault(c % p, []).append(value)
        model = {k: Counter(vs).most_common(1)[0][0]
                 for k, vs in by_residue.items()}

        # Restore the stepped left border before the patterned field.
        first_color = next((c for c, v in enumerate(row)
                            if c >= 3 and v not in (0, 1, 4)), None)
        if first_color is not None:
            for c in range(first_color):
                if row[c] == 0:
